export const buildPhraseTranslations: Partial<Record<Locale, Readonly<Record<string, string>>>> = Object.fromEntries(
  Object.keys({...baseBuildPhraseTranslations, ...buildPhraseUiFixes}).map((locale) => [locale, {
    ...baseBuildPhraseTranslations[locale as Locale],
    ...buildPhraseAdditions[locale as Locale],
    ...buildPhraseCoreAdditions[locale as Locale],
    ...buildPhraseUiFixes[locale as Locale],
    ...buildHelpGlossary[locale as Locale],
    ...mmoEditorPhraseTranslations[locale as Locale],
  }]),
) as Partial<Record<Locale, Readonly<Record<string, string>>>>;
